wrong_code.class:
// Degenerate point class with public fields — violates encapsulation!
public class Point {
    public double x;
    public double y;
}

wrong_code.call_site:
public class Main {
    public static void main(String[] args) {
        Point p = new Point();
        p.x = 10.5;
        p.y = 20.2;
        // Problems:
        // 1. Cannot change to polar coordinates (r, theta) without breaking all clients!
        // 2. Cannot enforce coordinate limits (e.g. non-negative).
        // 3. Not thread-safe.
    }
}

right_code.class:
// Encapsulated value class with private fields and accessors
public class Point {
    private double x;
    private double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getX() { return x; }
    public double getY() { return y; }

    public void setX(double x) { this.x = x; }
    public void setY(double y) { this.y = y; }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        Point p = new Point(10.5, 20.2);
        System.out.println("X: " + p.getX() + ", Y: " + p.getY());
        // The internal representation can now change freely
        // without affecting client code!
    }
}
